/**
 * Render the source of `host-core-modules.ts` from the `exports` map.
 *
 * Why a generated file: in a compiled binary (`bun build --compile`) there
 * is no `node_modules` and no `package.json` on disk, and `import.meta.dir`
 * is the virtual `/$bunfs/root`. The host-core resolver can then neither
 * find the core package nor `require` its export targets by a computed path.
 * A static `require()` per export makes the bundler include every public
 * module in the binary, and gives the resolver a loader for each specifier
 * that works the same from source and from a binary. Plugins load from disk
 * at run time and may import any public subpath, so every export must be in
 * the map.
 *
 * Why `require()` and not `import()`: the resolver's `build.module` callback
 * must stay synchronous. With an async callback, a plugin's `require()` of a
 * core subpath fails ("require() async module ... is unsupported"). Bun's
 * `require()` of an ES module returns the same namespace object as
 * `import()`, and no export target uses top-level await (the
 * "loads every export target" test requires each one).
 *
 * Kept apart from the generator script so the sync test can call it.
 *
 * @module plugins/loader/host-core-modules-render
 */

/** The package name of core. */
const CORE = "@minimal-agent/core"

/** The generated file, relative to the package root. */
export const HOST_CORE_MODULES_PATH = "src/plugins/loader/host-core-modules.ts"

/** From the generated file's dir back to the package root. */
const TO_ROOT = "../../.."

/** Biome's `lineWidth` (biome.json). */
const LINE_WIDTH = 100

/**
 * The specifier and the require path (relative to the generated file) of
 * each export, in `exports` order.
 *
 * @throws Error on a pattern key or a non-string target. The resolver
 *   serves exact specifiers only, so such an entry needs a design change.
 */
export function hostCoreModuleEntries(
  exportsMap: Record<string, unknown>,
): { specifier: string; importPath: string }[] {
  return Object.entries(exportsMap).map(([key, target]) => {
    if (!key.startsWith(".") || key.includes("*")) {
      throw new Error(`exports key ${key}: only exact subpath keys are served`)
    }
    if (typeof target !== "string" || !target.startsWith("./")) {
      throw new Error(`exports ${key}: the target must be a "./" path string`)
    }
    return {
      specifier: key === "." ? CORE : `${CORE}${key.slice(1)}`,
      importPath: `${TO_ROOT}/${target.slice(2)}`,
    }
  })
}

/**
 * The full text of `host-core-modules.ts` for `exportsMap`.
 *
 * @param exportsMap - The `exports` field of core's `package.json`.
 */
export function renderHostCoreModules(exportsMap: Record<string, unknown>): string {
  // Wrap like Biome (line width 100), so `bun run check` accepts the output as is.
  const lines = hostCoreModuleEntries(exportsMap).map(({ specifier, importPath }) => {
    const oneLine = `  "${specifier}": () => require("${importPath}"),`
    return oneLine.length <= LINE_WIDTH
      ? oneLine
      : `  "${specifier}": () =>\n    require("${importPath}"),`
  })
  return [
    "// GENERATED by scripts/gen-host-core-modules.ts from the package.json",
    "// `exports` map. Do not edit. Run `bun run gen:host-core-modules`.",
    "",
    "/**",
    " * One loader per public specifier of `@minimal-agent/core`, for the",
    " * host-core resolver. See `host-core-modules-render.ts`.",
    " *",
    " * @module plugins/loader/host-core-modules",
    " */",
    "",
    "/** Load the host's own module for a public specifier, synchronously. */",
    "export type HostCoreModuleLoader = () => unknown",
    "",
    "/** Each public specifier, in `exports` order, and its loader. */",
    "export const HOST_CORE_MODULES: Readonly<Record<string, HostCoreModuleLoader>> = {",
    ...lines,
    "}",
    "",
  ].join("\n")
}
